'use strict';
let mapData=null,mapTicker='BE',mapSelection=null,mapRequest=0,mapThesis='',boardPose={x:0,y:0,scale:1},boardGroups={},boardReset=true;
const mapKinds={cluster:'Buying overlap',political:'Political trade',insider:'Corporate insider',award:'Contract / grant',policy:'Policy',bill:'Bill',earnings:'Catalyst',agent:'Research lead',thesis:'Why now',company:'Company',market:'Market',contract:'Contract'};
const mapStatus={record:'Source record',sourced:'Sourced claim',candidate:'Unverified link',inference:'Hypothesis'};
async function openResearchMap(symbol=marketSymbol||'BE',thesis=''){setMapMode('stock');mapTicker=tickerValid(symbol)?symbol:'BE';mapThesis=thesis;boardReset=true;changeView('map');$('#mapTicker').value=mapTicker;await loadResearchMap()}
async function loadResearchMap(){if(mapMode==='people'){$('#mapStatus').textContent='Refreshing disclosures and prices…';await refreshLive();renderPeopleMap();return;}const request=++mapRequest;$('#mapStatus').textContent='Loading evidence…';try{const r=await getLiveJSON('/api/research/map?symbol='+mapTicker);if(request!==mapRequest)return;if(r.error)throw Error();mapData=r;mapSelection=mapThesis?'thesis:'+mapThesis:null;const theses=r.nodes.filter(n=>n.kind==='thesis');$('#mapThesis').innerHTML='<option value="">All research</option>'+theses.map(n=>`<option value="${esc(n.articleId)}">${esc(n.label)}</option>`).join('');$('#mapThesis').value=mapThesis;$('#mapThesis').hidden=!theses.length;renderMap();}catch{if(request===mapRequest)$('#mapStatus').textContent='Evidence unavailable. Try refresh.'}}
function visibleMapNodes(){if(!mapData)return [];const q=$('#mapSearch').value.toLowerCase();return mapData.nodes.filter(n=>n.kind!=='stock'&&($('#mapLeads').checked||n.status!=='candidate')&&(!mapThesis||n.kind!=='thesis'||n.articleId===mapThesis)&&(n.label+' '+n.detail+' '+(n.subtitle||'')).toLowerCase().includes(q))}
function boardGroupRows(nodes,group){const people=['political','insider'].includes(group),groups=new Map();for(const n of nodes){const key=people?n.label:n.id;const list=groups.get(key)||[];list.push(n);groups.set(key,list)}return [...groups].map(([label,items])=>({label:people?label:items[0].label,items}));}
function boardClues(nodes,group,empty){const rows=boardGroupRows(nodes,group);return rows.length?rows.slice(0,4).map(r=>`<button class="board-clue" ${r.items.length===1?`data-map-node="${esc(r.items[0].id)}"`:`data-map-person="${esc(r.label)}" data-map-group="${group}"`}><b>${esc(r.label)}</b><span>${r.items.length>1?r.items.length+' records · ':''}${esc(r.items[0].subtitle||r.items[0].detail||mapStatus[r.items[0].status])}</span><small>${esc(r.items[0].date||'Date unknown')}${r.items[0].status==='candidate'?' · unverified':''}</small></button>`).join('')+(rows.length>4?`<button class="board-more" data-board-group="${group}">See all ${nodes.length} records ↗</button>`:''):`<p class="board-empty">${empty}</p>`}
function renderMap(){if(mapMode==='people'){renderPeopleMap();return}if(!mapData)return;const nodes=visibleMapNodes(),group=k=>nodes.filter(n=>k.includes(n.kind));boardGroups={political:group(['political','cluster']),insider:group(['insider']),catalyst:group(['award','contract','policy','bill','earnings','company','agent']),price:group(['market']),thesis:group(['thesis'])};const theses=boardGroups.thesis,t=theses[0],leadCount=mapData.nodes.filter(n=>n.status==='candidate').length;
 const card=(key,title,kicker,content)=>`<section class="board-card board-${key}" data-board-card="${key}"><i class="board-pin" aria-hidden="true"></i><div class="board-kicker">${kicker}</div><h2>${title}</h2><span class="board-overview-count">${key==='stock'?'':key==='thesis'?boardGroups.thesis.length+' theories':(boardGroups[key]?.length||0)+' records'}</span>${content}</section>`;
 const strings=`<svg class="board-strings" viewBox="0 0 1120 820" aria-hidden="true"><g><path d="M410 400C370 400 380 180 330 180"/><path d="M710 400C750 400 740 180 790 180"/><path d="M410 400C370 400 380 590 330 590"/><path d="M710 400C750 400 740 590 790 590"/><path d="M560 480L560 550" class="string-inference"/></g></svg>`;
 $('#mapCanvas').innerHTML=`<div class="board-world" id="boardWorld">${strings}${card('stock',esc(mapTicker),'CENTRAL STOCK',`<p>${esc(mapData.nodes.find(n=>n.kind==='stock')?.detail||'Stock research')}</p><button data-ticker="${esc(mapTicker)}">Open chart ↗</button>`)}${card('political','Who is positioned?','POLITICAL DISCLOSURES',boardClues(boardGroups.political,'political','No political trades in the loaded evidence.'))}${card('insider','What are insiders doing?','COMPANY FILINGS',boardClues(boardGroups.insider,'insider','No corporate-insider records loaded.'))}${card('catalyst','What could move it?','CATALYSTS',boardClues(boardGroups.catalyst,'catalyst','No supported catalyst linked yet.')+(!$('#mapLeads').checked&&leadCount?`<button class="board-more" id="boardShowLeads">Inspect ${leadCount} unverified leads ↗</button>`:''))}${card('price','Has the price reacted?','MARKET RESPONSE',boardClues(boardGroups.price,'price','No price context loaded.'))}${card('thesis','Why this stock, now?','WORKING THEORY',t?`<button class="board-theory" data-map-node="${esc(t.id)}"><b>${esc(t.label)}</b><p>${esc(t.detail)}</p></button><p class="board-check"><b>Watch</b>${esc(t.watch)}</p><p class="board-check"><b>Breaks if</b>${esc(t.invalidation)}</p><button class="board-more" data-map-node="${esc(t.id)}">Follow the evidence ↗</button>${theses.length>1?`<button class="board-more" data-board-group="thesis">${theses.length} working theories ↗</button>`:''}`:'<p class="board-empty">The clues do not yet form a supported trading thesis.</p><p class="board-check"><b>Missing link</b>A sourced catalyst, a causal explanation and a condition that would prove it wrong.</p>')}</div>`;
 $('#mapStatus').textContent=nodes.length+' source records & research clues · '+(t?'working theory available':'thesis not established');
 $('#mapList').innerHTML=nodes.map(n=>`<button data-map-node="${esc(n.id)}" class="map-list-row"><b>${esc(n.label)}</b><span>${esc(mapKinds[n.kind]||n.kind)} · ${esc(mapStatus[n.status])} · ${esc(n.date||'Date unknown')}</span></button>`).join('')||'<p>No clues match this search.</p>';
 $('#mapCoverage').innerHTML=(mapData.coverage||[]).map(c=>`<p><b>${esc(c.source)}</b> · ${c.count} records · ${esc(c.state)}${c.checkedAt?' · '+esc(stamp(c.checkedAt)):''}</p>`).join('');
 if(boardReset){if($('#mapCanvas').clientWidth<650)focusBoard('stock');else fitBoard();boardReset=false}else applyBoardPose();
}
function applyBoardPose(){const el=$('#boardWorld');$('#mapCanvas').classList.toggle('board-overview',boardPose.scale<.65);if(el)el.style.transform=`translate(${boardPose.x}px,${boardPose.y}px) scale(${boardPose.scale})`;$('#boardZoomLevel').textContent=Math.round(boardPose.scale*100)+'%'}
function fitBoard(){const r=$('#mapCanvas').getBoundingClientRect(),w=mapMode==='people'?peopleSize.width:1120,h=mapMode==='people'?peopleSize.height:820,scale=Math.min(r.width/w,r.height/h,1);boardPose={scale,x:(r.width-w*scale)/2,y:(r.height-h*scale)/2};applyBoardPose()}
function zoomBoard(factor,x,y){const r=$('#mapCanvas').getBoundingClientRect();x??=r.width/2;y??=r.height/2;const old=boardPose.scale,next=Math.max(.04,Math.min(1.8,old*factor));boardPose={scale:next,x:x-(x-boardPose.x)*next/old,y:y-(y-boardPose.y)*next/old};applyBoardPose()}
function focusBoard(key){const el=document.querySelector('[data-board-card="'+key+'"]');if(!el)return;const r=$('#mapCanvas').getBoundingClientRect(),scale=Math.min(1.1,(r.width-28)/el.offsetWidth);boardPose={scale,x:r.width/2-(el.offsetLeft+el.offsetWidth/2)*scale,y:24-el.offsetTop*scale};applyBoardPose()}
function showMapInspector(){if(!$('#mapInspector').open)$('#mapInspector').showModal()}
function selectMapNode(id){mapSelection=id;renderMapDetail();showMapInspector()}
function showBoardGroup(group,person){const nodes=(boardGroups[group]||[]).filter(n=>!person||n.label===person);$('#mapDetail').innerHTML=`<small class="map-detail-status">${nodes.length} evidence records</small><h2>${esc(person||({political:'Political disclosures',insider:'Corporate insider filings',catalyst:'Potential catalysts',price:'Market context',thesis:'Working theories'}[group]||'Evidence'))}</h2><p class="muted">Select a record for dates, context and its original source.</p>${nodes.map(n=>`<button class="map-list-row" data-map-node="${esc(n.id)}"><b>${esc(n.subtitle||n.label)}</b><span>${esc(n.detail)}</span><small>${esc(n.date||'Date unknown')} · ${esc(mapStatus[n.status])}</small></button>`).join('')}`;showMapInspector()}

function renderMapDetail(){const n=mapData?.nodes.find(n=>n.id===mapSelection),el=$('#mapDetail');if(!n){const theses=mapData?.nodes.filter(n=>n.kind==='thesis')||[];el.innerHTML=`<h2>Why ${esc(mapTicker)} now?</h2>${theses.length?theses.slice(0,4).map(a=>`<button class="map-thesis" data-map-node="${esc(a.id)}"><b>${esc(a.label)}</b><span>${esc(a.detail)}</span></button>`).join(''):'<p>No supported thesis published yet. Select a record to inspect its dates and source. An apparent connection still needs a causal explanation and a catalyst.</p>'}<button class="secondary" data-ticker="${esc(mapTicker)}">Open price chart ↗</button>`;return}
 const relations=mapData.edges.filter(e=>e.from===n.id||e.to===n.id);el.innerHTML=`<small class="map-detail-status">${esc(mapKinds[n.kind]||n.kind)} · ${esc(mapStatus[n.status])}</small><h2>${esc(n.label)}</h2><p>${esc(n.detail)}</p><p class="muted">${n.date?'Source date '+date(n.date):'Source date unknown'}${n.eventDate?' · Event '+date(n.eventDate):''}<br>First observed ${n.firstObserved?esc(stamp(n.firstObserved)):'Not recorded'}</p>${n.provenance?'<p>'+esc(n.provenance)+'</p>':''}${n.url?researchLink(n.url,'Open original source ↗'):''}${n.kind!=='thesis'&&n.sources?n.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · '):''}${n.kind==='thesis'?`<dl class="map-thesis-fields"><dt>Why now</dt><dd>${esc(n.why)}</dd><dt>Already priced in?</dt><dd>${esc(n.pricedIn)}</dd><dt>Next confirmation</dt><dd>${esc(n.watch)}</dd><dt>Invalidation</dt><dd>${esc(n.invalidation)}</dd><dt>Counterargument</dt><dd>${esc(n.risk)}</dd><dt>Horizon</dt><dd>${esc(n.horizon)}</dd></dl>${n.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}${n.review?'<p><b>Latest review: '+esc(n.review.verdict)+'</b> '+esc(n.review.summary)+'</p>':''}<div id="mapThesisPerformance">Loading performance…</div>`:''}<h3>Connections</h3>${relations.map(e=>{const target=mapData.nodes.find(t=>t.id===(e.from===n.id?e.to:e.from));return target?`<button class="map-relation" data-map-node="${esc(target.id)}">${esc(e.relation)} → ${esc(target.label)}</button>`:''}).join('')}`;
 if(n.kind==='thesis'){const selected=n.id;getLiveJSON('/api/research/performance?id='+n.articleId).then(p=>{articleMetrics.set(n.articleId,p);if(mapSelection===selected&&$('#mapThesisPerformance'))$('#mapThesisPerformance').innerHTML=articlePerformanceHTML({id:n.articleId,tickers:[mapTicker]})}).catch(()=>{if(mapSelection===selected&&$('#mapThesisPerformance'))$('#mapThesisPerformance').textContent='Performance unavailable'})}
}

if(typeof window!=='undefined'){
 $('#mapForm').onsubmit=e=>{e.preventDefault();if(mapMode==='people'){const q=$('#mapSearch').value.toLowerCase(),n=[...peopleNodes.values()].find(n=>n.name.toLowerCase().includes(q));if(q&&n)focusPeopleNode(n.id);else if(politicianNames().includes($('#mapPerson').value))openPeopleMap($('#mapPerson').value);else notify('Choose a politician from the suggestions')}else openResearchMap($('#mapTicker').value.trim().toUpperCase())};$('#mapRefresh').onclick=loadResearchMap;
 $('#mapSearch').oninput=renderMap;$('#mapLeads').onchange=renderMap;$('#mapThesis').onchange=e=>{mapThesis=e.target.value;renderMap();focusBoard('thesis')};
 $('#boardFit').onclick=fitBoard;$('#boardZoomIn').onclick=()=>zoomBoard(1.25);$('#boardZoomOut').onclick=()=>zoomBoard(.8);$('#mapInspectorClose').onclick=()=>$('#mapInspector').close();
 let suppressClickUntil=0;$('#mapCanvas').addEventListener('click',e=>{if(Date.now()<suppressClickUntil){e.preventDefault();e.stopImmediatePropagation()}},{capture:true});
 document.addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const open=e.target.closest('[data-map]');if(open){if(open.dataset.map||open.dataset.thesis)openResearchMap(open.dataset.map||marketSymbol,open.dataset.thesis||'');else openPeopleMap();}const focus=e.target.closest('[data-board-focus]');if(focus)focusBoard(focus.dataset.boardFocus);
  const card=e.target.closest('[data-board-card]');if(card&&boardPose.scale<.65){focusBoard(card.dataset.boardCard);return}
  const n=e.target.closest('[data-map-node]');if(n)selectMapNode(n.dataset.mapNode);const person=e.target.closest('[data-map-person]');if(person)showBoardGroup(person.dataset.mapGroup,person.dataset.mapPerson);const group=e.target.closest('[data-board-group]');if(group)showBoardGroup(group.dataset.boardGroup);
  if(e.target.id==='boardShowLeads'){$('#mapLeads').checked=true;renderMap();focusBoard('catalyst')}
 });
 const canvas=$('#mapCanvas'),pointers=new Map();let moved=false,start=null,pinchDistance=null,startCard=null;
 canvas.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!e.target.closest('button'))canvas.setPointerCapture(e.pointerId);moved=false;start={x:e.clientX,y:e.clientY};startCard=e.target.closest('[data-board-card]')?.dataset.boardCard;canvas.classList.add('dragging');if(pointers.size===2){const p=[...pointers.values()];pinchDistance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}});
 canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const previous=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>5){moved=true;if(!canvas.hasPointerCapture(e.pointerId))canvas.setPointerCapture(e.pointerId);}
  if(pointers.size===2){const p=[...pointers.values()],distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),r=canvas.getBoundingClientRect();if(pinchDistance>0)zoomBoard(distance/pinchDistance,(p[0].x+p[1].x)/2-r.left,(p[0].y+p[1].y)/2-r.top);pinchDistance=distance;moved=true}else{boardPose.x+=e.clientX-previous.x;boardPose.y+=e.clientY-previous.y;applyBoardPose()}});
 const end=e=>{if(!pointers.has(e.pointerId))return;pointers.delete(e.pointerId);pinchDistance=null;if(moved)suppressClickUntil=Date.now()+200;else if(startCard&&boardPose.scale<.65)focusBoard(startCard);if(!pointers.size)canvas.classList.remove('dragging')};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
 canvas.addEventListener('wheel',e=>{if(!e.ctrlKey)return;e.preventDefault();const r=canvas.getBoundingClientRect();zoomBoard(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top)},{passive:false});
 canvas.addEventListener('keydown',e=>{if(e.target!==canvas)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','f','F'].includes(e.key))e.preventDefault();if(e.key==='+'||e.key==='=')zoomBoard(1.25);else if(e.key==='-')zoomBoard(.8);else if(e.key.toLowerCase()==='f')fitBoard();else{if(e.key==='ArrowLeft')boardPose.x+=60;if(e.key==='ArrowRight')boardPose.x-=60;if(e.key==='ArrowUp')boardPose.y+=60;if(e.key==='ArrowDown')boardPose.y-=60;applyBoardPose()}});
 let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(view==='map'){if($('#mapCanvas').clientWidth<650){if(mapMode==='people')focusPeopleNode('root');else focusBoard('stock')}else fitBoard()}},150)});setInterval(()=>{if(!document.hidden&&view==='map')loadResearchMap()},15*60000);
}
